public class DynQueue<T>{private T[]data;private int head,size;public DynQueue(T[]storage){data=storage;}public void put(Object value){if(size==data.length){T[]grown=java.util.Arrays.copyOf(data,data.length*2);for(int i=0;i<size;i++)grown[i]=data[(head+i)%data.length];data=grown;head=0;}data[(head+size++)%data.length]=(T)value;}public T get(){if(size==0){System.out.println("empty");return null;}T value=data[head];head=(head+1)%data.length;size--;return value;}}
